package suite

import (
	"fmt"
	"slices"
	"strconv"
	"strings"

	"github.com/ahillspace/tadx/tests/live/harness"
)

// BindingRequirements declares portable dependencies for every administration,
// catalog, and Pulse case. Native workbook/datasource fixtures are generated by
// setup; optional flow packages and external identities remain explicit.
func BindingRequirements() map[string][]string {
	out := map[string][]string{}
	for id := range AdminCases() {
		out[id] = []string{}
	}
	for id := range CatalogCases() {
		out[id] = []string{}
	}
	for id := range PulseCases() {
		out[id] = []string{"pulse_datasource"}
	}
	for _, verb := range []string{"list", "inspect", "update", "delete", "converge-members"} {
		out["live.admin-group."+verb] = []string{"user_a"}
	}
	out["live.admin-group.converge-members"] = []string{"user_a", "user_b"}
	for _, verb := range []string{"add", "remove"} {
		out["live.admin-group-member."+verb] = []string{"user_a", "user_b"}
	}
	for _, verb := range []string{"list", "inspect"} {
		out["live.admin-user."+verb] = []string{"user_a"}
	}
	for _, verb := range []string{"create", "update"} {
		out["live.admin-user."+verb] = []string{"controlled_user"}
	}
	out["live.admin-user.delete"] = []string{"controlled_user", "user_a"}
	out["live.admin-permission.flow"] = []string{"flow-native"}
	out["live.admin-permission.workbook"] = []string{"workbook-native"}
	out["live.admin-permission.datasource"] = []string{"datasource-native"}
	for _, verb := range []string{"read", "update", "delete"} {
		out["live.labels."+verb+"-attachment"] = []string{"datasource-native"}
	}
	for _, kind := range []string{"database", "table", "column"} {
		out["live.catalog."+kind+"-read"] = []string{"catalog_" + kind}
		out["live.catalog."+kind+"-update"] = []string{"catalog_" + kind, "catalog_" + kind + "_sibling", "user_b"}
	}
	for _, kind := range []string{"database", "table", "datasource", "workbook"} {
		out["live.catalog.audit-"+kind] = []string{"audit_" + kind}
	}
	out["live.catalog.search-upstream"] = []string{"catalog_search"}
	out["live.catalog.search-column-scope"] = []string{"catalog_column_search"}
	for _, kind := range []string{"workbook", "datasource", "flow"} {
		out["live.lineage."+kind+"-graph"] = []string{"lineage_" + kind}
	}
	for _, verb := range []string{"pull", "publish"} {
		out["live.pulse-definition."+verb] = []string{"pulse_datasource", "user_a"}
	}
	for _, verb := range []string{"followers", "follow", "follow-group", "unfollow"} {
		out["live.pulse-metric."+verb] = []string{"pulse_datasource", "user_a", "user_b"}
	}
	out["live.pulse-subscription.list"] = []string{"pulse_datasource", "user_b"}
	out["live.pulse-definition.publish"] = []string{"pulse_datasource", "user_a", "pulse_destination_datasource"}
	return out
}

// ValidateAssignedBindings checks authored prerequisites before fixture creation.
// Fresh REST reads still establish permissions, baseline values, and readiness.
func ValidateAssignedBindings(id string, p harness.Profile) error {
	keys, assigned := BindingRequirements()[id]
	if !assigned {
		return nil
	}
	for _, key := range keys {
		b, ok := p.Bindings[key]
		if key == "pulse_destination_datasource" && !ok {
			continue
		}
		if strings.Contains(key, "-native") {
			if !ok {
				return harness.Blocked("target profile requires native binding " + key)
			}
			if err := ValidateContentBinding(key, b); err != nil {
				return err
			}
			continue
		}
		if !ok {
			return harness.Blocked("target profile requires binding " + key)
		}
		if key == "controlled_user" {
			if harness.ValidateControlledUserTemplate(b.Name) != nil || b.Params["auth_setting"] == "" {
				return harness.Blocked("controlled_user requires {prefix} login template and auth_setting")
			}
			if id == "live.admin-user.update" && (b.Params["siteRole"] == "Viewer" || b.Params["site_role"] == "Viewer") {
				return harness.Blocked("role update requires controlled user baseline different from Viewer")
			}
			continue
		}
		if key == "catalog_search" || key == "catalog_column_search" {
			continue
		}
		if b.ID == "" {
			return harness.Blocked("binding " + key + " requires authoritative REST ID")
		}
	}
	if strings.HasPrefix(id, "live.catalog.") && strings.HasSuffix(id, "-read") {
		kind := strings.TrimSuffix(strings.TrimPrefix(id, "live.catalog."), "-read")
		b := p.Bindings["catalog_"+kind]
		if b.Name == "" || b.Params["metadata_id"] == "" {
			return harness.Blocked("catalog read requires exact name and metadata_id")
		}
		if kind != "database" && b.Params["parent_id"] == "" {
			return harness.Blocked("catalog table/column requires parent_id")
		}
		return validateOracle(b)
	}
	if strings.HasPrefix(id, "live.catalog.") && strings.HasSuffix(id, "-update") {
		kind := strings.TrimSuffix(strings.TrimPrefix(id, "live.catalog."), "-update")
		b, sibling := p.Bindings["catalog_"+kind], p.Bindings["catalog_"+kind+"_sibling"]
		if b.ID == sibling.ID {
			return harness.Blocked("catalog subject and sibling identities must differ")
		}
		if kind == "column" && (b.Params["parent_id"] == "" || sibling.Params["parent_id"] == "") {
			return harness.Blocked("column subject and sibling require parent_id")
		}
	}
	if strings.HasPrefix(id, "live.catalog.audit-") {
		kind := strings.TrimPrefix(id, "live.catalog.audit-")
		b := p.Bindings["audit_"+kind]
		if e := validateOracle(b); e != nil {
			return e
		}
		truth := asObject(b.Expected["output"])
		findings := array(truth["findings"])
		if len(findings) == 0 {
			return harness.Blocked("audit requires nonempty authored output.findings")
		}
		if n, e := strconv.Atoi(fmt.Sprint(truth["scanned"])); e != nil || n <= 0 {
			return harness.Blocked("audit requires positive authored scanned count")
		}
		if _, ok := truth["complete"].(bool); !ok {
			return harness.Blocked("audit requires explicit complete boolean")
		}
		summary := asObject(truth["summary"])
		for _, key := range []string{"present", "missing", "unknown"} {
			n, e := strconv.Atoi(fmt.Sprint(summary[key]))
			if e != nil || n < 0 {
				return harness.Blocked("audit requires nonnegative present/missing/unknown totals")
			}
		}
		states := map[string]bool{}
		for _, v := range findings {
			f := asObject(v)
			if f["metadata_id"] == "" || f["metadata_id"] == nil || f["check"] == nil || f["source"] == nil || f["state"] == nil {
				return harness.Blocked("every authored finding requires metadata_id, check, source, and state")
			}
			states[fmt.Sprint(f["state"])] = true
			states[fmt.Sprint(f["source"])] = true
		}
		if (kind == "datasource" || kind == "workbook") && (!states["direct"] || !states["inherited"] || !states["missing"]) {
			return harness.Blocked("field audit requires authored direct, inherited, and missing descriptions")
		}
	}
	if id == "live.catalog.search-upstream" || id == "live.catalog.search-column-scope" {
		key := "catalog_search"
		if id == "live.catalog.search-column-scope" {
			key = "catalog_column_search"
		}
		b := p.Bindings[key]
		if e := validateOracle(b); e != nil {
			return e
		}
		if b.Params["query"] == "" || len(array(asObject(b.Expected["output"])["items"])) == 0 {
			return harness.Blocked("catalog search requires query and nonempty exact output.items")
		}
		if key == "catalog_column_search" && b.Params["parent_id"] == "" {
			return harness.Blocked("column search requires parent_id")
		}
	}
	if strings.HasPrefix(id, "live.lineage.") {
		kind := strings.TrimSuffix(strings.TrimPrefix(id, "live.lineage."), "-graph")
		b := p.Bindings["lineage_"+kind]
		if e := validateOracle(b); e != nil {
			return e
		}
		truth := asObject(b.Expected["graph"])
		if b.Params["metadata_id"] == "" || len(array(truth["nodes"])) < 2 || len(array(truth["edges"])) == 0 {
			return harness.Blocked("lineage requires root metadata_id and nonempty independently authored graph")
		}
	}
	if strings.HasPrefix(id, "live.pulse-") {
		b := p.Bindings["pulse_datasource"]
		for _, key := range []string{"measure_field", "date_field", "dimension_field"} {
			if b.Params[key] == "" {
				return harness.Blocked("pulse_datasource requires exact " + key)
			}
		}
		if id == "live.pulse-definition.pull" || id == "live.pulse-definition.publish" || id == "live.pulse-metric.fork" {
			if b.Params["category"] == "" {
				return harness.Blocked("Pulse portable/fork fixtures require authored category")
			}
		}
	}
	if a, ok := p.Bindings["user_a"]; ok && slices.Contains(keys, "user_a") && slices.Contains(keys, "user_b") {
		if b, ok := p.Bindings["user_b"]; ok && a.ID == b.ID {
			return harness.Blocked("user_a and user_b must be distinct site users")
		}
	}
	return nil
}
func validateOracle(b harness.Binding) error {
	truth := asObject(b.Expected["oracle"])
	if b.Params["oracle_query"] == "" || len(truth) == 0 {
		return harness.Blocked("catalog binding requires read-only oracle_query and nonempty authored Expected.oracle")
	}
	return nil
}

// AssignedFixtureCapabilities declares independent provisioning and cleanup
// writes for the assigned contracts. Native content publication is declared by
// binding dependencies and is added by the coordinator.
func AssignedFixtureCapabilities(id string) []string {
	category := []string{"admin.label.category.create", "admin.label.category.delete"}
	value := append(slices.Clone(category), "admin.label.value.update", "admin.label.value.delete")
	group := []string{"admin.group.create", "admin.group.delete"}
	pulseDefinition := []string{"pulse.definition.create", "pulse.definition.delete"}
	pulseVariant := append(slices.Clone(pulseDefinition), "pulse.metric.fork", "pulse.metric.delete")
	pulseFollower := append(slices.Clone(pulseVariant), "pulse.metric.follow", "pulse.metric.unfollow")
	var capabilities []string
	switch id {
	case "live.admin-group.create":
		capabilities = []string{"admin.group.delete"}
	case "live.admin-group.list", "live.admin-group.inspect", "live.admin-group.update", "live.admin-group.delete", "live.admin-group.converge-members", "live.admin-group-member.add", "live.admin-group-member.remove":
		capabilities = append(slices.Clone(group), "admin.group.member.add")
	case "live.admin-user.create":
		capabilities = []string{"admin.user.delete"}
	case "live.admin-user.update", "live.admin-user.delete":
		capabilities = []string{"admin.user.create", "admin.user.delete"}
	case "live.admin-label-category.create":
		capabilities = []string{"admin.label.category.delete"}
	case "live.admin-label-category.list", "live.admin-label-category.inspect", "live.admin-label-category.update", "live.admin-label-category.delete":
		capabilities = category
	case "live.admin-label-value.list", "live.admin-label-value.inspect", "live.admin-label-value.delete":
		capabilities = value
	case "live.admin-label-value.upsert":
		capabilities = append(slices.Clone(category), "admin.label.value.delete")
	case "live.admin-permission.project", "live.admin-permission.workbook", "live.admin-permission.datasource", "live.admin-permission.flow", "live.admin-permission.defaults-workbooks", "live.admin-permission.defaults-datasources", "live.admin-permission.defaults-flows":
		capabilities = append(slices.Clone(group), "admin.permission.create")
	case "live.labels.read-attachment", "live.labels.update-attachment", "live.labels.delete-attachment":
		capabilities = append(slices.Clone(value), "content.label.update", "content.label.delete")
	case "live.catalog.database-update":
		capabilities = []string{"catalog.database.update"}
	case "live.catalog.table-update":
		capabilities = []string{"catalog.table.update"}
	case "live.catalog.column-update":
		capabilities = []string{"catalog.column.update"}
	case "live.pulse-definition.create":
		capabilities = []string{"pulse.definition.delete"}
	case "live.pulse-definition.list", "live.pulse-definition.inspect", "live.pulse-definition.delete":
		capabilities = pulseDefinition
	case "live.pulse-definition.pull", "live.pulse-definition.publish":
		capabilities = pulseFollower
	case "live.pulse-metric.list", "live.pulse-metric.inspect", "live.pulse-metric.fork", "live.pulse-metric.delete":
		capabilities = pulseVariant
	case "live.pulse-metric.follow", "live.pulse-metric.followers", "live.pulse-metric.unfollow":
		capabilities = pulseFollower
	case "live.pulse-metric.follow-group":
		capabilities = append(slices.Clone(pulseFollower), group...)
	case "live.pulse-subscription.list":
		capabilities = append(slices.Clone(pulseDefinition), "pulse.metric.follow", "pulse.metric.unfollow")
	}
	slices.Sort(capabilities)
	return slices.Compact(capabilities)
}
